sys_script.script:
(function executeRule(current, previous) {

    // Only when Reminder Sent changes false → true
    if (!current.reminder_sent.changesTo(true)) {
        return;
    }

    // Student notification only for Collection deadlines
    if (current.getValue('deadline_type') != 'collection') {
        return;
    }

    if (!current.getValue('user')) {
        return;
    }

    var n = new GlideRecord(
        'x_snc_campusmatch_campusmatch_notification'
    );

    n.initialize();

    n.setValue('recipient', current.getValue('user'));
    n.setValue('audience', 'student');
    n.setValue('notification_type', 'deadline');

    n.setValue(
        'title',
        'Collection deadline approaching'
    );

    n.setValue(
        'message',
        'Your verified item is waiting at the Security Desk. Please collect it before ' +
        current.getDisplayValue('due_date_time') + '.'
    );

    n.setValue(
        'source_table',
        'x_snc_campusmatch_campusmatch_deadline'
    );

    n.setValue(
        'source_sys_id',
        current.getUniqueValue()
    );

    n.setValue('read', false);

    n.setValue(
        'dedupe_key',
        'collection_deadline_' + current.getUniqueValue()
    );

    n.insert();

})(current, previous);
